param([Parameter(Mandatory=$true)][ValidateSet('ck')][string]$Action)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-float-alignment-product-20260913';$source='D:\projects\AIMA-public-float-alignment-qk-20260913'
$sha='6c0c54c3e540ad075f18e9cf77e5c9f759938f4a';$bundle='D:\projects\float-alignment-product-6c0c54c.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '6b3256270edb908237b1bf58f928ae2b74d1eb0bb749757b758d5c998e1bba79'){throw 'Bundle changed'}
